	(1, 1, 'Un comentarista de WordPress', 'wapuu@wordpress.example', 'https://pe.wordpress.org/', '', '2026-11-06 11:22:05', '2026-11-06 16:22:05', 'Hola, esto es un comentario.\nPara empezar a moderar, editar y borrar comentarios, por favor, visita en el escritorio la pantalla de comentarios.\nLos avatares de los comentaristas provienen de <a href="https://gravatar.com/">Gravatar</a>.', 0, '1', '', 'comment', 0, 0),
	(2, 234, 'WooCommerce', '', '', '', '2026-11-17 09:16:33', '2026-11-17 14:16:33', 'Awaiting BACS payment. Order status changed from Pending payment to On hold.', 0, '1', 'WooCommerce', 'order_note', 0, 0),
