	(237, 1, '2026-11-17 10:09:25', '2026-11-17 15:09:25', '{"settings":{"color":{"palette":{"theme":[{"slug":"primary","color":"#7545FC","name":"Primary"},{"slug":"secondary","color":"#7F0AF5","name":"Secondary"},{"slug":"primary-shade-one","color":"#442599","name":"Primary Shade 1"},{"slug":"primary-shade-2","color":"#150E3A","name":"Primary Shade 2"},{"slug":"secondary-shade-1","color":"#3B2488","name":"Secondary Shade 1"},{"slug":"secondary-shade-2","color":"#6731FC","name":"Secondary Shade 2"},{"slug":"light-color","color":"#bdd6d3","name":"Light Color"},{"slug":"black-color","color":"#000000","name":"Black Color"},{"slug":"dark-shade","color":"#19192A","name":"Dark Shade"},{"slug":"heading-color","color":"#d6d6e1","name":"Heading Color"},{"slug":"background","color":"#0C0C13","name":"Background"},{"slug":"background-alt","color":"#0F0F1A","name":"Background Alt"},{"slug":"foreground","color":"#aeaecd","name":"Foreground"},{"slug":"foreground-alt","color":"#cee3e1","name":"Foreground Alternative"},{"slug":"meta-color","color":"#BEBACA","name":"Meta Color"},{"slug":"border-color","color":"#1F1A3D","name":"Border Color"},{"slug":"sticky-bg-color","color":"#021411","name":"Sticky Background Color"},{"color":"#ffffff00","name":"Transparent","slug":"transparent"},{"color":"#3182CE","name":"Brand Primary","slug":"palette1"},{"color":"#2B6CB0","name":"Brand Secondary","slug":"palette2"},{"color":"#1A202C","name":"Neutral 900","slug":"palette3"},{"color":"#2D3748","name":"Neutral 700","slug":"palette4"},{"color":"#4A5568","name":"Neutral 600","slug":"palette5"},{"color":"#718096","name":"Neutral 500","slug":"palette6"},{"color":"#EDF2F7","name":"Neutral 100","slug":"palette7"},{"color":"#ffffff","name":"Neutral 50","slug":"palette8"},{"color":"#ED8936","name":"Complement","slug":"palette10"},{"color":"#13612e","name":"Success","slug":"palette11"},{"color":"#1159af","name":"Info","slug":"palette12"},{"color":"#b82105","name":"Alert","slug":"palette13"},{"color":"#f7630c","name":"Warning","slug":"palette14"},{"color":"#f5a524","name":"Rating","slug":"palette15"}],"default":[{"name":"Negro","slug":"black","color":"#000000"},{"name":"Gris azulado cian","slug":"cyan-bluish-gray","color":"#abb8c3"},{"name":"Blanco","slug":"white","color":"#cededb"},{"name":"Rosa p\\u00e1lido","slug":"pale-pink","color":"#f78da7"},{"name":"Rojo vivo","slug":"vivid-red","color":"#cf2e2e"},{"name":"Naranja vivo luminoso","slug":"luminous-vivid-orange","color":"#ff6900"},{"name":"\\u00c1mbar vivo luminoso","slug":"luminous-vivid-amber","color":"#fcb900"},{"name":"Cian verde claro","slug":"light-green-cyan","color":"#7bdcb5"},{"name":"Cian verde vivo","slug":"vivid-green-cyan","color":"#00d084"},{"name":"Azul cian p\\u00e1lido","slug":"pale-cyan-blue","color":"#8ed1fc"},{"name":"Azul cian vivo","slug":"vivid-cyan-blue","color":"#0693e3"},{"name":"Morado vivo","slug":"vivid-purple","color":"#9b51e0"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '227-revision-v1', '', '', '2026-11-17 10:09:25', '2026-11-17 15:09:25', '', 227, 'http://localhost:81/tienda-2/?p=237', 0, 'revision', '', 0),
	(238, 1, '2026-11-17 10:12:01', '2026-11-17 15:12:01', '{\n    "custom_css[saaslauncher]": {\n        "value": "/* Cambiar fondo general a blanco y texto a oscuro */\\nbody, .site, .site-content, .content-area, .woocommerce {\\n    background-color: #ffffff !important;\\n    color: #111111 !important;\\n}\\n/* Asegurar visibilidad en tarjetas de productos */\\n.woocommerce ul.products li.product, .woocommerce-page ul.products li.product {\\n    background-color: #ffffff !important;\\n    color: #111111 !important;\\n}",\n        "type": "custom_css",\n        "user_id": 1,\n        "date_modified_gmt": "2026-11-17 15:11:54"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'cb8fe4eb-c1eb-4c08-a62b-2dee3ea56762', '', '', '2026-11-17 10:12:01', '2026-11-17 15:12:01', '', 0, 'http://localhost:81/tienda-2/?p=238', 0, 'customize_changeset', '', 0),
	(239, 1, '2026-11-17 10:12:01', '2026-11-17 15:12:01', '/* 1. Mantener el fondo general oscuro de la tienda */\nbody, .site, .site-main, .wp-site-blocks {\n    background-color: #0b0b0f !important;\n}\n\n/* 2. Tarjeta blanca llamativa y profesional para cada producto (FSE + Clásico) */\nul.products li.product,\nul.wc-block-product-template li.wc-block-product,\n.wc-block-grid__products .wc-block-grid__product,\n.woocommerce ul.products li.product {\n    background-color: #ffffff !important;\n    border-radius: 16px !important;\n    padding: 20px !important;\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.6) !important;\n    border: 1px solid rgba(255, 255, 255, 0.15) !important;\n    transition: transform 0.25s ease, box-shadow 0.25s ease !important;\n    display: flex !important;\n    flex-direction: column !important;\n    justify-content: space-between !important;\n    text-align: center !important;\n    overflow: hidden !important;\n}\n\n/* Efecto profesional al pasar el cursor (Hover) */\nul.products li.product:hover,\nul.wc-block-product-template li.wc-block-product:hover,\n.wc-block-grid__products .wc-block-grid__product:hover {\n    transform: translateY(-6px) !important;\n    box-shadow: 0 14px 30px rgba(108, 92, 231, 0.35) !important;\n}\n\n/* 3. Estilo limpio para la imagen dentro de la tarjeta blanca */\nul.products li.product img,\nul.wc-block-product-template li.wc-block-product img {\n    border-radius: 10px !important;\n    margin-bottom: 14px !important;\n    object-fit: contain !important;\n    background-color: #ffffff !important;\n}\n\n/* 4. Títulos y precios oscuros y legibles dentro de la tarjeta */\nul.products li.product .woocommerce-loop-product__title,\nul.products li.product h2,\nul.products li.product h3,\nul.wc-block-product-template li.wc-block-product .wp-block-post-title a,\nul.products li.product .price,\nul.products li.product .price bdi,\nul.wc-block-product-template li.wc-block-product .wc-block-components-product-price {\n    color: #111111 !important;\n    font-weight: 700 !important;\n}\n\n/* 5. Botón de compra estilizado al ancho de la tarjeta */\nul.products li.product .button,\nul.wc-block-product-template li.wc-block-product .wp-block-button__link {\n    border-radius: 10px !important;\n    padding: 12px 16px !important;\n    font-weight: 600 !important;\n    width: 100% !important;\n    margin-top: 12px !important;\n    box-sizing: border-box !important;\n}\n\n\n\n\n/* Banner encabezado de categoría deportivo y profesional */\n.woocommerce-products-header,\n.wp-block-query-title,\n.term-description {\n    position: relative !important;\n    padding: 36px 24px !important;\n    margin: 16px auto 24px auto !important;\n    border-radius: 16px !important;\n    background: linear-gradient(135deg, #121521 0%, #1c2237 65%, #252d4a 100%) !important;\n    border: 1px solid rgba(255, 255, 255, 0.12) !important;\n    border-bottom: 4px solid #6c5ce7 !important;\n    box-shadow: 0 12px 28px rgba(0, 0, 0, 0.45) !important;\n    text-align: center !important;\n}\n\n/* Título principal de categoría (CAMISETAS) más llamativo */\n.woocommerce-products-header__title,\nh1.page-title,\nh1.wp-block-query-title {\n    color: #ffffff !important;\n    font-size: clamp(2rem, 4vw, 3.2rem) !important;\n    font-weight: 800 !important;\n    letter-spacing: 0.08em !important;\n    text-transform: uppercase !important;\n    margin: 0 0 8px 0 !important;\n    text-shadow: 0 4px 14px rgba(0, 0, 0, 0.5) !important;\n}\n\n/* Migas de pan (Home / CAMISETAS) en formato píldora limpia */\n.woocommerce-breadcrumb,\n.woocommerce-breadcrumb a {\n    color: #cbd5e1 !important;\n    font-size: 0.88rem !important;\n    letter-spacing: 0.03em !important;\n    text-decoration: none !important;\n}\n\n.woocommerce-breadcrumb a:hover {\n    color: #a29bfe !important;\n}\n\n\n\n/* Cuadro blanco profesional para el bloque de imagen y galería en producto individual */\n.single-product .wp-block-columns .wp-block-column:first-child,\n.single-product .woocommerce-product-gallery,\n.single-product .wp-block-woocommerce-product-image-gallery,\n.single-product div.product div.images {\n    background-color: #ffffff !important;\n    border-radius: 18px !important;\n    padding: 22px !important;\n    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.55) !important;\n    border: 1px solid #e5e7eb !important;\n    box-sizing: border-box !important;\n    overflow: hidden !important;\n}\n\n/* Asegurar que elementos internos dentro de ese cuadro no vuelvan a oscurecerse */\n.single-product .wp-block-columns .wp-block-column:first-child .wp-block-group,\n.single-product .woocommerce-product-gallery__wrapper,\n.single-product .woocommerce-product-gallery__image {\n    background-color: #ffffff !important;\n    border-radius: 12px !important;\n}\n\n/* Ajustar tamaño del balón y miniaturas para que quepan holgados dentro del recuadro */\n.single-product .woocommerce-product-gallery__wrapper img,\n.single-product .wp-block-woocommerce-product-image-gallery img {\n    max-height: 360px !important;\n    width: 100% !important;\n    object-fit: contain !important;\n    background-color: #ffffff !important;\n}\n\n.single-product .flex-control-thumbs {\n    display: flex !important;\n    gap: 10px !important;\n    margin-top: 14px !important;\n    padding-top: 12px !important;\n    border-top: 1px solid #e5e7eb !important;\n}\n\n.single-product .flex-control-thumbs li {\n    flex: 1 1 0 !important;\n    list-style: none !important;\n    border-radius: 10px !important;\n    overflow: hidden !important;\n    border: 2px solid #e5e7eb !important;\n    background-color: #ffffff !important;\n}\n\n.single-product .flex-control-thumbs li img {\n    width: 100% !important;\n    height: 68px !important;\n    object-fit: contain !important;\n}', 'saaslauncher', '', 'publish', 'closed', 'closed', '', 'saaslauncher', '', '', '2026-11-20 07:10:52', '2026-11-20 12:10:52', '', 0, 'http://localhost:81/tienda-2/saaslauncher/', 0, 'custom_css', '', 0),
	(240, 1, '2026-11-17 10:12:01', '2026-11-17 15:12:01', '/* Cambiar fondo general a blanco y texto a oscuro */\nbody, .site, .site-content, .content-area, .woocommerce {\n    background-color: #ffffff !important;\n    color: #111111 !important;\n}\n/* Asegurar visibilidad en tarjetas de productos */\n.woocommerce ul.products li.product, .woocommerce-page ul.products li.product {\n    background-color: #ffffff !important;\n    color: #111111 !important;\n}', 'saaslauncher', '', 'inherit', 'closed', 'closed', '', '239-revision-v1', '', '', '2026-11-17 10:12:01', '2026-11-17 15:12:01', '', 239, 'http://localhost:81/tienda-2/?p=240', 0, 'revision', '', 0),
	(241, 1, '2026-11-17 10:17:43', '2026-11-17 15:17:43', '{\n    "custom_css[saaslauncher]": {\n        "value": "/* Cambiar fondo general a blanco y texto a oscuro */\\nbody, .site, .site-content, .content-area, .woocommerce {\\n    background-color: #ffffff !important;\\n    color: #111111 !important;\\n}\\n/* Asegurar visibilidad en tarjetas de productos */\\n.woocommerce ul.products li.product, .woocommerce-page ul.products li.product {\\n    background-color: #ffffff !important;\\n    color: #111111 !important;\\n}\\n\\n/* Forzar fondo blanco en bloques y contenedores internos */\\n.wp-block-group, .wp-block-cover, .site-main, .entry-content, div.ast-container {\\n    background-color: #ffffff !important;\\n}\\n/* Asegurar visibilidad de t\\u00edtulos de secci\\u00f3n */\\nh1, h2, h3, h4, h5, h6, p, span {\\n    color: #111111 !important;\\n}\\n\\n\\n\\n/* Cambiar fondo de la barra de navegaci\\u00f3n superior a blanco o gris claro */\\nheader.site-header, .site-header, .main-header-bar, nav.main-navigation, .ast-main-header-wrap {\\n    background-color: #ffffff !important;\\n    border-bottom: 1px solid #eaeaea !important;\\n}\\n/* Asegurar que los enlaces y textos del men\\u00fa superior sean oscuros */\\n.site-header a, .main-navigation a, .main-header-menu a, .site-title a {\\n    color: #111111 !important;\\n}",\n        "type": "custom_css",\n        "user_id": 1,\n        "date_modified_gmt": "2026-11-17 15:17:43"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'd9a5f2e7-2c31-422e-86a2-8c2186873e5f', '', '', '2026-11-17 10:17:43', '2026-11-17 15:17:43', '', 0, 'http://localhost:81/tienda-2/?p=241', 0, 'customize_changeset', '', 0),
	(242, 1, '2026-11-17 10:17:43', '2026-11-17 15:17:43', '/* Cambiar fondo general a blanco y texto a oscuro */\nbody, .site, .site-content, .content-area, .woocommerce {\n    background-color: #ffffff !important;\n    color: #111111 !important;\n}\n/* Asegurar visibilidad en tarjetas de productos */\n.woocommerce ul.products li.product, .woocommerce-page ul.products li.product {\n    background-color: #ffffff !important;\n    color: #111111 !important;\n}\n\n/* Forzar fondo blanco en bloques y contenedores internos */\n.wp-block-group, .wp-block-cover, .site-main, .entry-content, div.ast-container {\n    background-color: #ffffff !important;\n}\n/* Asegurar visibilidad de títulos de sección */\nh1, h2, h3, h4, h5, h6, p, span {\n    color: #111111 !important;\n}\n\n\n\n/* Cambiar fondo de la barra de navegación superior a blanco o gris claro */\nheader.site-header, .site-header, .main-header-bar, nav.main-navigation, .ast-main-header-wrap {\n    background-color: #ffffff !important;\n    border-bottom: 1px solid #eaeaea !important;\n}\n/* Asegurar que los enlaces y textos del menú superior sean oscuros */\n.site-header a, .main-navigation a, .main-header-menu a, .site-title a {\n    color: #111111 !important;\n}', 'saaslauncher', '', 'inherit', 'closed', 'closed', '', '239-revision-v1', '', '', '2026-11-17 10:17:43', '2026-11-17 15:17:43', '', 239, 'http://localhost:81/tienda-2/?p=242', 0, 'revision', '', 0),
	(243, 1, '2026-11-20 06:43:37', '2026-11-20 11:43:37', '{\n    "custom_css[saaslauncher]": {\n        "value": "/* 1. Mantener el fondo general oscuro de la tienda */\\nbody, .site, .site-main, .wp-site-blocks {\\n    background-color: #0b0b0f !important;\\n}\\n\\n/* 2. Tarjeta blanca llamativa y profesional para cada producto (FSE + Cl\\u00e1sico) */\\nul.products li.product,\\nul.wc-block-product-template li.wc-block-product,\\n.wc-block-grid__products .wc-block-grid__product,\\n.woocommerce ul.products li.product {\\n    background-color: #ffffff !important;\\n    border-radius: 16px !important;\\n    padding: 20px !important;\\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.6) !important;\\n    border: 1px solid rgba(255, 255, 255, 0.15) !important;\\n    transition: transform 0.25s ease, box-shadow 0.25s ease !important;\\n    display: flex !important;\\n    flex-direction: column !important;\\n    justify-content: space-between !important;\\n    text-align: center !important;\\n    overflow: hidden !important;\\n}\\n\\n/* Efecto profesional al pasar el cursor (Hover) */\\nul.products li.product:hover,\\nul.wc-block-product-template li.wc-block-product:hover,\\n.wc-block-grid__products .wc-block-grid__product:hover {\\n    transform: translateY(-6px) !important;\\n    box-shadow: 0 14px 30px rgba(108, 92, 231, 0.35) !important;\\n}\\n\\n/* 3. Estilo limpio para la imagen dentro de la tarjeta blanca */\\nul.products li.product img,\\nul.wc-block-product-template li.wc-block-product img {\\n    border-radius: 10px !important;\\n    margin-bottom: 14px !important;\\n    object-fit: contain !important;\\n    background-color: #ffffff !important;\\n}\\n\\n/* 4. T\\u00edtulos y precios oscuros y legibles dentro de la tarjeta */\\nul.products li.product .woocommerce-loop-product__title,\\nul.products li.product h2,\\nul.products li.product h3,\\nul.wc-block-product-template li.wc-block-product .wp-block-post-title a,\\nul.products li.product .price,\\nul.products li.product .price bdi,\\nul.wc-block-product-template li.wc-block-product .wc-block-components-product-price {\\n    color: #111111 !important;\\n    font-weight: 700 !important;\\n}\\n\\n/* 5. Bot\\u00f3n de compra estilizado al ancho de la tarjeta */\\nul.products li.product .button,\\nul.wc-block-product-template li.wc-block-product .wp-block-button__link {\\n    border-radius: 10px !important;\\n    padding: 12px 16px !important;\\n    font-weight: 600 !important;\\n    width: 100% !important;\\n    margin-top: 12px !important;\\n    box-sizing: border-box !important;\\n}",\n        "type": "custom_css",\n        "user_id": 1,\n        "date_modified_gmt": "2026-11-20 11:43:37"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '60c333c5-df51-43b7-b71e-0d3704c026fd', '', '', '2026-11-20 06:43:37', '2026-11-20 11:43:37', '', 0, 'http://localhost:81/tienda-2/?p=243', 0, 'customize_changeset', '', 0),
