over {\\n    color: #a29bfe !important;\\n}\\n\\n\\n\\n/* Contenedor blanco profesional para la galer\\u00eda principal y sus miniaturas */\\n.single-product div.product .woocommerce-product-gallery,\\n.wp-block-woocommerce-product-image-gallery {\\n    background-color: #ffffff !important;\\n    border-radius: 18px !important;\\n    padding: 24px !important;\\n    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.55) !important;\\n    border: 1px solid rgba(255, 255, 255, 0.15) !important;\\n    box-sizing: border-box !important;\\n}\\n\\n/* Ajustar la imagen principal dentro del recuadro blanco */\\n.single-product div.product .woocommerce-product-gallery__wrapper img,\\n.wp-block-woocommerce-product-image-gallery img {\\n    border-radius: 12px !important;\\n    object-fit: contain !important;\\n}\\n\\n/* Estilizar las miniaturas (diferentes tomas) de abajo */\\n.single-product div.product .flex-control-thumbs {\\n    display: flex !important;\\n    gap: 10px !important;\\n    margin-top: 16px !important;\\n    padding-top: 14px !important;\\n    border-top: 1px solid #eaeaea !important;\\n}\\n\\n.single-product div.product .flex-control-thumbs li {\\n    border-radius: 10px !important;\\n    overflow: hidden !important;\\n    border: 2px solid transparent !important;\\n    transition: transform 0.2s ease, border-color 0.2s ease !important;\\n}\\n\\n.single-product div.product .flex-control-thumbs li:hover,\\n.single-product div.product .flex-control-thumbs li img.flex-active {\\n    border-color: #6c5ce7 !important;\\n    transform: translateY(-2px) !important;\\n}",\n        "type": "custom_css",\n        "user_id": 1,\n        "date_modified_gmt": "2026-11-20 12:07:54"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'e42d0a40-ffd0-4ccc-9ec6-1c3953afac2a', '', '', '2026-11-20 07:07:54', '2026-11-20 12:07:54', '', 0, 'http://localhost:81/tienda-2/?p=248', 0, 'customize_changeset', '', 0),
